	opts := []vesapi.CallOpt{
		vesapi.WithFailIfReferred(),
	}

	err = r.client.DeleteObject(ctx, ves_io_schema_network_policy_rule.ObjectType, data.Namespace.ValueString(), data.Name.ValueString(), opts...)

